import {normalizeMix,tracks} from './mix.js';
export function suggestedInstruments(style){const defaults={melody:false,harmony:true,bass:true,drums:false,piano:true,guitar:false,violin:false};return {...defaults,...({rnb:{piano:true,guitar:true,drums:true},folk:{piano:false,guitar:true,violin:true},ballad:{piano:true,violin:true,drums:true},rock:{piano:false,guitar:true,drums:true,harmony:false},electronic:{piano:false,melody:true,drums:true}}[style]||{})}}
export function arrangerHtml(p,score){const mix=normalizeMix(p.mix),sec=n=>(n*score.duration).toFixed(1),enabled=Object.keys(tracks).filter(k=>p.instruments[k]);return `<section class="arranger" aria-label="回忆编曲台"><div class="arranger-heading"><div><div class="eyebrow">MAKE IT YOUR OWN</div><h2>你的回忆，你来编曲。</h2></div><span class="live-label">● 实时试听</span></div><p class="arranger-intro">每种乐器可以反复出场。拆成小段，再决定它在哪些时刻发声。</p><div class="tempo-panel"><label for="tempo">回忆的步速 <strong id="tempo-value">${score.bpm} BPM</strong></label><input id="tempo" type="range" min="60" max="150" step="1" value="${score.bpm}" aria-label="音乐速度"><div class="tempo-labels"><span>慢慢回想</span><span>轻快向前</span></div><button class="secondary" id="apply-tempo">应用速度</button><p>调整速度会重新演奏同一条旋律，保持音高。</p></div><div class="arrange-presets"><button data-preset="build">✧ 渐进展开</button><button data-preset="dialogue">♡ 双人对话</button><button data-preset="intimate">☾ 私密独白</button></div><div class="timeline-heading"><span>声音的出场顺序</span><span>每种乐器最多 16 段</span></div><div class="arrange-lanes">${enabled.map(k=>`<div class="arrange-lane" data-lane="${k}"><div class="lane-heading"><b>${tracks[k]}</b><span>${mix[k].segments.length} 个片段</span><button class="spotlight" data-spotlight="${k}">此刻高光</button></div><div class="segment-overview">${mix[k].segments.map(seg=>`<i style="left:${seg.start*100}%;width:${(seg.end-seg.start)*100}%"></i>`).join('')}</div>${mix[k].segments.map((seg,i)=>`<div class="segment-row" data-segment="${i}"><div class="segment-heading"><b>片段 ${i+1}</b><span data-window-label>${sec(seg.start)}s — ${sec(seg.end)}s</span><button data-split-segment="${k}:${i}" aria-label="拆分${tracks[k]}片段${i+1}">拆分</button><button data-delete-segment="${k}:${i}" aria-label="删除${tracks[k]}片段${i+1}">删除</button></div><div class="window-rail" style="--from:${seg.start*100}%;--to:${seg.end*100}%"><div class="lane-grid"></div><div class="window-region"><span>♫</span></div><input class="trim-range trim-start" type="range" min="0" max="95" step="1" value="${Math.round(seg.start*100)}" data-mix="start" data-segment-index="${i}" data-track-mix="${k}" aria-label="${tracks[k]}片段${i+1}进入时间百分比"><input class="trim-range trim-end" type="range" min="1" max="100" step="1" value="${Math.round(seg.end*100)}" data-mix="end" data-segment-index="${i}" data-track-mix="${k}" aria-label="${tracks[k]}片段${i+1}离开时间百分比"></div></div>`).join('')}<button class="add-segment" data-add-segment="${k}">＋ 添加一个片段</button><div class="lane-volume"><span>音量</span><input type="range" min="0" max="150" step="1" value="${Math.round(mix[k].volume*100)}" data-mix="volume" data-track-mix="${k}" aria-label="${tracks[k]}音量"><output data-volume-label="${k}">${Math.round(mix[k].volume*100)}%</output></div></div>`).join('')||'<p class="hint">先在上方选中一种乐器，再安排它的出场。</p>'}</div><div class="arrange-actions"><button class="text-btn" id="undo-arrange">撤回一次调整</button><button class="text-btn" id="reset-arrange">恢复整段演奏</button><button class="primary" id="save-arrange">保存编曲</button></div><p class="arrange-footnote">拆分会在两段之间留出短暂停顿；拖动两端调整每个片段。试听、收藏、备份与音频下载均保留多个片段。</p></section>`}
